:root {
  --bg: #f4f5f7;
  --card: #ffffff;
  --ink: #1f2933;
  --muted: #6b7a8c;
  --line: #e4e7eb;
  --accent: #2563eb;
  --accent-dark: #1d4ed8;
  --danger: #dc2626;
  --danger-soft: #fef2f2;
  --radius: 14px;
  --shadow: 0 1px 3px rgba(16, 24, 40, .06), 0 8px 24px rgba(16, 24, 40, .06);
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "PingFang SC", "Microsoft YaHei", sans-serif;
  background: var(--bg);
  color: var(--ink);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}
.app {
  max-width: 560px;
  margin: 0 auto;
  padding: 24px 16px 48px;
}
header h1 {
  margin: 0 0 4px;
  font-size: 1.6rem;
  letter-spacing: -.01em;
}
.subtitle {
  margin: 0 0 20px;
  color: var(--muted);
  font-size: .9rem;
}
.summary {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  background: linear-gradient(135deg, #1e3a8a, #2563eb);
  color: #fff;
  border-radius: var(--radius);
  padding: 20px 22px;
  box-shadow: var(--shadow);
  margin-bottom: 18px;
}
.summary-label {
  font-size: .85rem;
  opacity: .85;
}
.summary-value {
  font-size: 1.9rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.add-form {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 16px;
  box-shadow: var(--shadow);
}
.field { display: flex; flex-direction: column; gap: 6px; }
.field label {
  font-size: .8rem;
  font-weight: 600;
  color: var(--muted);
}
.field input {
  width: 100%;
  padding: 10px 12px;
  font-size: 1rem;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: #fbfcfd;
  color: var(--ink);
  transition: border-color .15s, box-shadow .15s;
}
.field input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, .15);
}
.field input.invalid {
  border-color: var(--danger);
  box-shadow: 0 0 0 3px rgba(220, 38, 38, .12);
}
.btn-add {
  grid-column: 1 / -1;
  padding: 12px;
  font-size: 1rem;
  font-weight: 600;
  color: #fff;
  background: var(--accent);
  border: none;
  border-radius: 10px;
  cursor: pointer;
  transition: background .15s, transform .05s;
}
.btn-add:hover { background: var(--accent-dark); }
.btn-add:active { transform: translateY(1px); }
.error-msg {
  margin: 8px 2px 0;
  color: var(--danger);
  font-size: .85rem;
}
.list-section { margin-top: 26px; }
.list-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}
.list-head h2 {
  margin: 0;
  font-size: 1.05rem;
}
.count-badge {
  font-size: .78rem;
  color: var(--muted);
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 3px 10px;
}
.empty-state {
  text-align: center;
  color: var(--muted);
  background: var(--card);
  border: 1px dashed var(--line);
  border-radius: var(--radius);
  padding: 36px 20px;
}
.empty-icon { font-size: 2.2rem; margin-bottom: 8px; }
.empty-state p { margin: 4px 0; }
.empty-hint { font-size: .85rem; }
.expense-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.expense-item {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 12px 14px;
  box-shadow: var(--shadow);
}
.item-main { flex: 1; min-width: 0; }
.item-name {
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.item-time {
  font-size: .75rem;
  color: var(--muted);
}
.item-amount {
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.btn-del {
  flex-shrink: 0;
  width: 34px;
  height: 34px;
  border-radius: 9px;
  border: 1px solid transparent;
  background: var(--danger-soft);
  color: var(--danger);
  font-size: 1.1rem;
  line-height: 1;
  cursor: pointer;
  transition: background .15s, border-color .15s;
}
.btn-del:hover { background: #fee2e2; border-color: #fecaca; }
.btn-del:focus-visible,
.btn-add:focus-visible,
.btn-clear:focus-visible {
  outline: 3px solid rgba(37, 99, 235, .4);
  outline-offset: 2px;
}
.app-footer { margin-top: 20px; text-align: center; }
.btn-clear {
  background: none;
  border: none;
  color: var(--muted);
  font-size: .85rem;
  cursor: pointer;
  padding: 8px 12px;
  border-radius: 8px;
}
.btn-clear:hover { color: var(--danger); background: var(--danger-soft); }
@media (max-width: 480px) {
  .add-form { grid-template-columns: 1fr; }
  .summary-value { font-size: 1.6rem; }
}

