(function () {
  'use strict';

  var STORAGE_KEY = 'feeyuan_expenses_v1';

  // ---- DOM refs ----
  var nameInput = document.getElementById('nameInput');
  var amountInput = document.getElementById('amountInput');
  var addBtn = document.getElementById('addBtn');
  var errorMsg = document.getElementById('errorMsg');
  var totalDisplay = document.getElementById('totalDisplay');
  var countBadge = document.getElementById('countBadge');
  var emptyState = document.getElementById('emptyState');
  var expenseList = document.getElementById('expenseList');
  var clearAllBtn = document.getElementById('clearAllBtn');
  var form = document.getElementById('expenseForm');

  // Prevent native submission entirely.
  if (form) form.addEventListener('submit', function (e) { e.preventDefault(); });

  // ---- State ----
  var expenses = loadExpenses();

  function loadExpenses() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      var parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed.filter(function (item) {
        return item && typeof item === 'object' &&
          typeof item.id === 'string' &&
          typeof item.name === 'string' &&
          typeof item.amount === 'number' &&
          isFinite(item.amount);
      }).map(function (item) {
        return {
          id: item.id,
          name: item.name.slice(0, 40),
          amount: Math.max(0, item.amount),
          ts: typeof item.ts === 'number' ? item.ts : Date.now()
        };
      });
    } catch (err) {
      console.warn('读取本地数据失败，已重置。', err);
      return [];
    }
  }

  function saveExpenses() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
    } catch (err) {
      showError('保存失败：浏览器存储不可用或已满。');
    }
  }

  // ---- Helpers ----
  function formatMoney(value) {
    return '\u00A5' + value.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  }

  function formatDate(ts) {
    var d = new Date(ts);
    if (isNaN(d.getTime())) return '';
    var pad = function (n) { return n < 10 ? '0' + n : '' + n; };
    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) +
      ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes());
  }

  function showError(msg) {
    errorMsg.textContent = msg;
    errorMsg.hidden = false;
  }

  function clearError() {
    errorMsg.hidden = true;
    errorMsg.textContent = '';
    nameInput.classList.remove('invalid');
    amountInput.classList.remove('invalid');
  }

  function makeId() {
    return 'id_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8);
  }

  // ---- Actions ----
  function addExpense() {
    clearError();

    var name = nameInput.value.trim();
    var rawAmount = amountInput.value.trim();
    var amount = parseFloat(rawAmount);

    if (!name) {
      nameInput.classList.add('invalid');
      showError('请输入费用名称。');
      nameInput.focus();
      return;
    }
    if (rawAmount === '' || isNaN(amount)) {
      amountInput.classList.add('invalid');
      showError('请输入有效的金额。');
      amountInput.focus();
      return;
    }
    if (amount <= 0) {
      amountInput.classList.add('invalid');
      showError('金额必须大于 0。');
      amountInput.focus();
      return;
    }
    if (!isFinite(amount)) {
      amountInput.classList.add('invalid');
      showError('金额数值过大。');
      return;
    }

    // Round to cents to avoid float drift.
    amount = Math.round(amount * 100) / 100;

    expenses.unshift({
      id: makeId(),
      name: name.slice(0, 40),
      amount: amount,
      ts: Date.now()
    });

    saveExpenses();
    render();

    nameInput.value = '';
    amountInput.value = '';
    nameInput.focus();
  }

  function deleteExpense(id) {
    var before = expenses.length;
    expenses = expenses.filter(function (e) { return e.id !== id; });
    if (expenses.length !== before) {
      saveExpenses();
      render();
    }
  }

  function clearAll() {
    if (expenses.length === 0) return;
    if (!window.confirm('确定要清空全部记录吗？此操作无法撤销。')) return;
    expenses = [];
    saveExpenses();
    render();
  }

  // ---- Render ----
  function render() {
    var total = expenses.reduce(function (sum, e) { return sum + e.amount; }, 0);
    totalDisplay.textContent = formatMoney(total);
    countBadge.textContent = expenses.length + ' 条';

    clearAllBtn.hidden = expenses.length === 0;

    if (expenses.length === 0) {
      emptyState.style.display = '';
      expenseList.innerHTML = '';
      return;
    }

    emptyState.style.display = 'none';

    var frag = document.createDocumentFragment();
    expenses.forEach(function (e) {
      var li = document.createElement('li');
      li.className = 'expense-item';

      var main = document.createElement('div');
      main.className = 'item-main';

      var nameEl = document.createElement('div');
      nameEl.className = 'item-name';
      nameEl.textContent = e.name;
      nameEl.title = e.name;

      var timeEl = document.createElement('div');
      timeEl.className = 'item-time';
      timeEl.textContent = formatDate(e.ts);

      main.appendChild(nameEl);
      main.appendChild(timeEl);

      var amountEl = document.createElement('div');
      amountEl.className = 'item-amount';
      amountEl.textContent = formatMoney(e.amount);

      var delBtn = document.createElement('button');
      delBtn.type = 'button';
      delBtn.className = 'btn-del';
      delBtn.setAttribute('aria-label', '删除记录：' + e.name + '，' + formatMoney(e.amount));
      delBtn.textContent = '\u00D7';
      delBtn.dataset.id = e.id;

      li.appendChild(main);
      li.appendChild(amountEl);
      li.appendChild(delBtn);
      frag.appendChild(li);
    });

    expenseList.innerHTML = '';
    expenseList.appendChild(frag);
  }

  // ---- Events ----
  addBtn.addEventListener('click', addExpense);
  clearAllBtn.addEventListener('click', clearAll);

  // Delete via event delegation on the results container only.
  expenseList.addEventListener('click', function (e) {
    var btn = e.target.closest('.btn-del');
    if (btn && btn.dataset.id) {
      deleteExpense(btn.dataset.id);
    }
  });

  // Enter in either field adds a record (keyboard friendly).
  nameInput.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') { e.preventDefault(); addExpense(); }
  });
  amountInput.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') { e.preventDefault(); addExpense(); }
  });

  // Clear inline invalid styling as the user corrects input.
  nameInput.addEventListener('input', function () {
    nameInput.classList.remove('invalid');
    if (!errorMsg.hidden) clearError();
  });
  amountInput.addEventListener('input', function () {
    amountInput.classList.remove('invalid');
    if (!errorMsg.hidden) clearError();
  });

  // Initial render right after mount.
  render();
})();
